			this.directDamage(source.maxhp / 2, source, source);
			if (source.isAlly(target)) {
				const random = this.getRandomTarget(source, 'Curse');
				if (!random) return false;
				target = random;
			}
			delete target.volatiles['curse'];
			target.addVolatile('curse');
		},
